let selectedSlug=creators[0]?.slug||'',siteContent={...window.C3_SITE_CONTENT},panels=JSON.parse(JSON.stringify(window.C3_PANELS||[])),selectedPanelSlug=window.C3_PANELS?.[0]?.slug||'',communities=JSON.parse(JSON.stringify(window.C3_COMMUNITIES||[])).map(item=>{const initial=(window.C3_COMMUNITIES_DEFAULTS||[]).find(entry=>entry.slug===item.slug)||{};return {...initial,...item,thematicEnabled:item.slug==='skepsis-gaming'?false:item.thematicEnabled!==false,thematicAreas:Array.isArray(item.thematicAreas)?item.thematicAreas:(initial.thematicAreas||[])}}),selectedCommunitySlug=window.C3_COMMUNITIES?.[0]?.slug||'';
let macrocategories=window.C3_REMOTE_MACROCATEGORIES||JSON.parse(localStorage.getItem(MACRO_KEY)||'null')||['Host','Cosplay','Panel & talk','Workshop','Performance','Gaming & GdR','Community & contenuti','Attività in fiera'];
const defaultCreatorFilters=[['fantasy','Fantasy'],['gaming','Gaming'],['gdr-gdt','GDR/GDT'],['cosplay','Cosplay'],['musica','Musica'],['pop','Pop culture'],['divulgazione','Divulgazione']].map(([slug,label])=>({slug,label}));
