const creatorFilterRoot=document.querySelector('#creator-filters'),creatorFilterList=document.querySelector('#creator-filter-list'),newCreatorFilter=document.querySelector('#new-creator-filter');
function renderCreatorFilters(active=[]){creatorFilterRoot.innerHTML=creatorFilters.map(item=>`<label><input type="checkbox" value="${escapeHtml(item.slug)}" ${active.includes(item.slug)?'checked':''}><span>${escapeHtml(item.label)}</span></label>`).join('');filterInputs=[...creatorFilterRoot.querySelectorAll('input')];creatorFilterList.innerHTML=creatorFilters.map((item,index)=>`<span class="macrocategory-item"><input value="${escapeHtml(item.label)}" data-filter-index="${index}" aria-label="Modifica ${escapeHtml(item.label)}"><button type="button" data-remove-filter="${index}" aria-label="Elimina ${escapeHtml(item.label)}">×</button></span>`).join('')}
async function saveCreatorFilters(){creatorFilters=creatorFilters.filter((item,index,list)=>item.slug&&item.label&&list.findIndex(other=>other.slug===item.slug)===index);localStorage.setItem(FILTER_KEY,JSON.stringify(creatorFilters));window.C3_REMOTE_CREATOR_FILTERS=creatorFilters;try{await window.C3_BACKEND?.saveSetting('creator_filters',creatorFilters);return true}catch(error){setStatus(statusRoot,`Filtri salvati solo su questo computer: ${error.message}`);return false}}
