document.querySelector('#add-creator-filter').addEventListener('click',async()=>{const label=newCreatorFilter.value.trim(),slug=slugify(label);if(!label||!slug)return;if(creatorFilters.some(item=>item.slug===slug)){setStatus(statusRoot,`Il filtro “${label}” esiste già.`);return}const active=filterInputs.filter(input=>input.checked).map(input=>input.value);creatorFilters.push({slug,label});active.push(slug);renderCreatorFilters(active);newCreatorFilter.value='';await saveCreatorFilters();renderOrder();setStatus(statusRoot,`Filtro “${label}” aggiunto e disponibile nel sito.`)});
