creatorFilterList.addEventListener('change',async event=>{const input=event.target.closest('[data-filter-index]');if(!input)return;const index=Number(input.dataset.filterIndex),label=input.value.trim();if(!label){renderCreatorFilters(filterInputs.filter(item=>item.checked).map(item=>item.value));return}creatorFilters[index].label=label;const active=filterInputs.filter(item=>item.checked).map(item=>item.value);renderCreatorFilters(active);await saveCreatorFilters();renderOrderTabs();setStatus(statusRoot,'Nome del filtro aggiornato online.')});
creatorFilterList.addEventListener('click',async event=>{const button=event.target.closest('[data-remove-filter]');if(!button)return;const index=Number(button.dataset.removeFilter),removed=creatorFilters[index];if(!removed)return;const used=creators.some(creator=>(creator.filters||[]).includes(removed.slug));if(used&&!confirm(`Il filtro “${removed.label}” è assegnato ad alcuni creator. Vuoi eliminarlo anche da quelle schede?`))return;creators.forEach(creator=>{creator.filters=(creator.filters||[]).filter(slug=>slug!==removed.slug)});creatorFilters.splice(index,1);delete categoryOrders[removed.slug];renderCreatorFilters();await Promise.all([saveCreatorFilters(),window.C3_BACKEND?.saveCreators(creators),window.C3_BACKEND?.saveSetting('creator_order_categories',categoryOrders)]);localStorage.setItem(CREATOR_KEY,JSON.stringify(creators));renderOrder();setStatus(statusRoot,`Filtro “${removed.label}” eliminato.`)});
const parseTerritories=value=>value.split(',').map(v=>v.trim()).filter(Boolean).map(v=>{const [area,...region]=v.split(':');return{area:area.trim().toLowerCase(),region:region.join(':').trim()}}).filter(v=>['nord','centro','sud'].includes(v.area)&&v.region);
