const socialPlaceholders={Instagram:'https://instagram.com/nomecreator',TikTok:'https://tiktok.com/@nomecreator',YouTube:'https://youtube.com/@nomecreator',Facebook:'https://facebook.com/nomecreator',Twitch:'https://twitch.tv/nomecreator',Spotify:'https://open.spotify.com/artist/...','Sito web':'https://www.sitocreator.it'};
