const macroSelectOptions=selected=>`<option value="">Scegli macroarea</option>${macrocategories.map(item=>`<option value="${escapeHtml(item)}" ${item===selected?'selected':''}>${escapeHtml(item)}</option>`).join('')}`;
function refreshActivityOrderButtons(){const rows=[...activityEditor.querySelectorAll('.activity-row')];rows.forEach((row,index)=>{row.querySelector('[data-activity-move="up"]').disabled=index===0;row.querySelector('[data-activity-move="down"]').disabled=index===rows.length-1})}
function activityRow(activity={title:'',description:'',group:''}){const value=typeof activity==='string'?{title:activity,description:genericDescription(activity,fields.name.value||'Il creator'),group:''}:activity;const group=value.group||'';if(group&&!macrocategories.some(item=>item.toLocaleLowerCase('it')===group.toLocaleLowerCase('it')))macrocategories.push(group);const row=document.createElement('div');row.className='activity-row';row.innerHTML=`<select class="activity-group" aria-label="Macroarea attività">${macroSelectOptions(group)}</select><input class="activity-title" value="${escapeHtml(value.title)}" placeholder="Titolo attività" aria-label="Titolo attività"><textarea class="activity-description" placeholder="Spiegazione dell’attività" aria-label="Descrizione attività">${escapeHtml(value.description)}</textarea><div class="activity-actions"><button type="button" data-activity-move="up" aria-label="Sposta panel su">↑</button><button type="button" data-activity-move="down" aria-label="Sposta panel giù">↓</button><button class="remove-activity" type="button" aria-label="Elimina attività">×</button></div>`;row.querySelector('.remove-activity').addEventListener('click',()=>{row.remove();refreshActivityOrderButtons()});row.querySelectorAll('[data-activity-move]').forEach(button=>button.addEventListener('click',()=>{const sibling=button.dataset.activityMove==='up'?row.previousElementSibling:row.nextElementSibling;if(!sibling)return;activityEditor.insertBefore(button.dataset.activityMove==='up'?row:sibling,button.dataset.activityMove==='up'?sibling:row);refreshActivityOrderButtons()}));activityEditor.append(row);refreshActivityOrderButtons()}
function readActivities(){return [...activityEditor.querySelectorAll('.activity-row')].map(row=>({group:row.querySelector('.activity-group').value.trim(),title:row.querySelector('.activity-title').value.trim(),description:row.querySelector('.activity-description').value.trim()})).filter(item=>item.title)}
function renderActivities(items=[]){activityEditor.innerHTML='';items.forEach(activityRow);if(!items.length)activityRow()}
const macroList=document.querySelector('#macrocategory-list'),macroOptions=document.querySelector('#macrocategory-options');
