function saveMacrocategories(){macrocategories=macrocategories.map(item=>item.trim()).filter((item,index,list)=>item&&list.findIndex(other=>other.toLocaleLowerCase('it')===item.toLocaleLowerCase('it'))===index);try{window.C3_LOCAL_DRAFT=null;localStorage.setItem(MACRO_KEY,JSON.stringify(macrocategories));window.C3_BACKEND?.saveSetting('macrocategories',macrocategories).catch(error=>setStatus(statusRoot,`Macroaree non salvate online: ${error.message}`));renderMacrocategories();refreshActivityGroupOptions();return true}catch{setStatus(statusRoot,'Impossibile salvare le macroaree nel browser.');return false}}
function renderMacrocategories(){macroOptions.innerHTML=macrocategories.map(item=>`<option value="${escapeHtml(item)}"></option>`).join('');macroList.innerHTML=macrocategories.map((item,index)=>`<span class="macrocategory-item"><input value="${escapeHtml(item)}" data-macro-index="${index}" aria-label="Modifica ${escapeHtml(item)}"><button type="button" data-remove-macro="${index}" aria-label="Elimina ${escapeHtml(item)}">×</button></span>`).join('')}
function addMacrocategory(rawValue,{notify=true}={}){const value=rawValue.trim();if(!value)return false;const existing=macrocategories.find(item=>item.toLocaleLowerCase('it')===value.toLocaleLowerCase('it'));if(existing){if(notify)setStatus(statusRoot,`La macroarea “${existing}” esiste già.`);return false}macrocategories.push(value);saveMacrocategories();if(notify)setStatus(statusRoot,`Macroarea “${value}” aggiunta.`);return true}
const newMacroInput=document.querySelector('#new-macrocategory');
document.querySelector('#add-macrocategory').addEventListener('click',()=>{if(addMacrocategory(newMacroInput.value))newMacroInput.value=''});
newMacroInput.addEventListener('keydown',event=>{if(event.key!=='Enter')return;event.preventDefault();if(addMacrocategory(newMacroInput.value))newMacroInput.value=''});
macroList.addEventListener('change',event=>{const input=event.target.closest('[data-macro-index]');if(!input)return;const draftActivities=readActivities(),index=Number(input.dataset.macroIndex),old=macrocategories[index],next=input.value.trim();if(!next){renderMacrocategories();return}const duplicate=macrocategories.find((item,itemIndex)=>itemIndex!==index&&item.toLocaleLowerCase('it')===next.toLocaleLowerCase('it'));if(duplicate){setStatus(statusRoot,`La macroarea “${duplicate}” esiste già.`);renderMacrocategories();return}macrocategories[index]=next;draftActivities.forEach(activity=>{if(activity.group===old)activity.group=next});creators.forEach(creator=>(creator.activities||[]).forEach(activity=>{if(activity&&typeof activity==='object'&&activity.group===old)activity.group=next}));saveCreators();saveMacrocategories();renderActivities(draftActivities);setStatus(statusRoot,`Macroarea rinominata in “${next}”.`)});
macroList.addEventListener('click',event=>{const button=event.target.closest('[data-remove-macro]');if(!button)return;const draftActivities=readActivities(),index=Number(button.dataset.removeMacro),removed=macrocategories[index],isUsed=creators.some(creator=>(creator.activities||[]).some(activity=>activity&&typeof activity==='object'&&activity.group===removed))||draftActivities.some(activity=>activity.group===removed);if(isUsed&&!confirm(`La categoria “${removed}” è già utilizzata. Eliminarla e lasciare senza macroarea le attività collegate?`))return;draftActivities.forEach(activity=>{if(activity.group===removed)activity.group=''});creators.forEach(creator=>(creator.activities||[]).forEach(activity=>{if(activity&&typeof activity==='object'&&activity.group===removed)activity.group=''}));macrocategories.splice(index,1);saveCreators();saveMacrocategories();renderActivities(draftActivities);setStatus(statusRoot,`Macroarea “${removed}” eliminata.`)});
renderMacrocategories();
function renderList(filter=''){const query=filter.toLowerCase();listRoot.innerHTML=creators.filter(item=>`${item.name} ${item.category}`.toLowerCase().includes(query)).map(item=>`<button type="button" class="creator-row ${item.slug===selectedSlug?'active':''}" data-slug="${escapeHtml(item.slug)}">${item.image?`<img src="${escapeHtml(item.image)}" alt="">`:`<span class="mini">${escapeHtml(item.name.slice(0,2).toUpperCase())}</span>`}<span><b>${escapeHtml(item.name)}</b><small>${escapeHtml(item.category)}</small></span></button>`).join('');listRoot.querySelectorAll('.creator-row').forEach(button=>button.addEventListener('click',()=>selectCreator(button.dataset.slug)))}
const photoPreview=document.querySelector('#photo-preview'),photoPreviewFrame=document.querySelector('#photo-preview-frame'),imagePositionX=document.querySelector('#image-position-x'),imagePositionY=document.querySelector('#image-position-y'),imageZoom=document.querySelector('#image-zoom');
function updatePhotoPreview(){const x=Number(imagePositionX.value),y=Number(imagePositionY.value),zoom=Number(imageZoom.value)/100;photoPreview.style.objectPosition=`${x}% ${y}%`;photoPreview.style.objectFit='cover';photoPreview.style.transformOrigin=`${x}% ${y}%`;photoPreview.style.transform=`scale(${zoom})`;document.querySelector('#image-position-x-output').value=`${x}%`;document.querySelector('#image-position-y-output').value=`${y}%`;document.querySelector('#image-zoom-output').value=`${Math.round(zoom*100)}%`}
[imagePositionX,imagePositionY,imageZoom].forEach(input=>input.addEventListener('input',updatePhotoPreview));
const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));
const touchDistance=touches=>Math.hypot(touches[0].clientX-touches[1].clientX,touches[0].clientY-touches[1].clientY);
let photoGesture=null;
photoPreviewFrame.addEventListener('touchstart',event=>{if(event.touches.length>=2){photoGesture={type:'pinch',distance:touchDistance(event.touches),zoom:Number(imageZoom.value)};event.preventDefault();return}if(event.touches.length===1){photoGesture={type:'pan',x:event.touches[0].clientX,y:event.touches[0].clientY,positionX:Number(imagePositionX.value),positionY:Number(imagePositionY.value)};event.preventDefault()}},{passive:false});
photoPreviewFrame.addEventListener('touchmove',event=>{if(!photoGesture)return;if(event.touches.length>=2){if(photoGesture.type!=='pinch')photoGesture={type:'pinch',distance:touchDistance(event.touches),zoom:Number(imageZoom.value)};const distance=touchDistance(event.touches),next=clamp(photoGesture.zoom*(distance/photoGesture.distance),Number(imageZoom.min),Number(imageZoom.max));imageZoom.value=Math.round(next/5)*5;updatePhotoPreview();event.preventDefault();return}if(event.touches.length===1&&photoGesture.type==='pan'){const bounds=photoPreviewFrame.getBoundingClientRect(),deltaX=event.touches[0].clientX-photoGesture.x,deltaY=event.touches[0].clientY-photoGesture.y;imagePositionX.value=clamp(photoGesture.positionX-(deltaX/bounds.width)*100,0,100);imagePositionY.value=clamp(photoGesture.positionY-(deltaY/bounds.height)*100,0,100);updatePhotoPreview();event.preventDefault()}},{passive:false});
photoPreviewFrame.addEventListener('touchend',event=>{if(!event.touches.length){photoGesture=null;return}if(event.touches.length===1)photoGesture={type:'pan',x:event.touches[0].clientX,y:event.touches[0].clientY,positionX:Number(imagePositionX.value),positionY:Number(imagePositionY.value)}},{passive:true});
function selectCreator(slug){const creator=creators.find(item=>item.slug===slug);if(!creator)return;selectedSlug=slug;fields['original-slug'].value=creator.slug;fields.name.value=creator.name;fields.slug.value=creator.slug;fields.category.value=creator.category;fields.meta.value=creator.meta||'';fields['card-description'].value=creator.cardDescription||creator.description;fields.description.value=creator.description;fields.image.value=creator.image||'';fields.territories.value=(creator.territories||[]).map(item=>`${item.area}:${item.region}`).join(', ');fields.socials.value=stringifySocials(creator.socials?.length?creator.socials:socialDefaults(creator.slug));renderAssignedSocials();const activeFilters=inferredFilters(creator);renderCreatorFilters(activeFilters);renderActivities(creator.activities||[]);photoPreview.src=creator.image||'assets/c3-agency-logo.png?v=3';imagePositionX.value=creator.imagePositionX??50;imagePositionY.value=creator.imagePositionY??50;imageZoom.value=creator.imageZoom??100;updatePhotoPreview();renderList(document.querySelector('#search').value)}
function newCreator(){selectedSlug='';HTMLFormElement.prototype.reset.call(form);fields['original-slug'].value='';fields.image.value='';fields.socials.value='';renderAssignedSocials();renderCreatorFilters();renderActivities();photoPreview.src='assets/c3-agency-logo.png?v=3';imagePositionX.value=50;imagePositionY.value=50;imageZoom.value=100;updatePhotoPreview();renderList(document.querySelector('#search').value);fields.name.focus();setStatus(statusRoot,'Nuova scheda pronta: compila i campi e premi Salva modifiche.')}
function optimizeImage(file,callback){const image=new Image();image.onload=()=>{const max=1000,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);callback(canvas.toDataURL('image/jpeg',.8));URL.revokeObjectURL(image.src)};image.src=URL.createObjectURL(file)}
fields.name.addEventListener('input',()=>{if(!fields['original-slug'].value)fields.slug.value=slugify(fields.name.value)});
document.querySelector('#photo').addEventListener('change',event=>{const file=event.target.files[0];if(file)optimizeImage(file,data=>{fields.image.value=data;photoPreview.src=data;updatePhotoPreview()})});
document.querySelector('#add-activity').addEventListener('click',()=>activityRow());
form.addEventListener('submit',event=>{event.preventDefault();const slug=slugify(fields.slug.value||fields.name.value);if(!slug)return;if(creators.some(item=>item.slug===slug&&item.slug!==fields['original-slug'].value)){setStatus(statusRoot,'Questo indirizzo è già utilizzato da un altro creator.');return}const activities=readActivities();activities.forEach(activity=>{if(activity.group)addMacrocategory(activity.group,{notify:false})});const record={slug,name:fields.name.value.trim(),category:fields.category.value.trim(),cardDescription:fields['card-description'].value.trim(),description:fields.description.value.trim(),meta:fields.meta.value.trim(),image:fields.image.value,imagePositionX:Number(imagePositionX.value),imagePositionY:Number(imagePositionY.value),imageZoom:Number(imageZoom.value),activities,territories:parseTerritories(fields.territories.value),filters:filterInputs.filter(input=>input.checked).map(input=>input.value),socials:parseSocials(fields.socials.value)};const index=creators.findIndex(item=>item.slug===fields['original-slug'].value),previous=index>=0?creators[index]:null;if(index>=0)creators[index]=record;else creators.push(record);if(!saveCreators()){if(index>=0)creators[index]=previous;else creators.pop();return}selectedSlug=slug;selectCreator(slug);setStatus(statusRoot,'Creator, descrizioni, foto, attività, social e filtri salvati.')});
document.querySelector('#new-creator').addEventListener('click',newCreator);document.querySelector('#search').addEventListener('input',e=>renderList(e.target.value));
